import 'package:flutter_test/flutter_test.dart';
import 'package:quizaipro_mobile/features/flashcards/domain/algorithms/fsrs_algorithm.dart';

/// Pins the Dart FSRS scheduler to the backend `fsrs.py`. The expected numbers
/// were generated by the Python implementation for the same review sequence.
/// Intervals must match EXACTLY (that's what drives scheduling); stability /
/// difficulty may differ only by float rounding noise.
void main() {
  test('FSRS Dart matches Python reference (intervals exact)', () {
    // Review sequence: (rating, elapsedDaysBeforeReview).
    // ratings: 1=Again, 2=Hard, 3=Good, 4=Easy.
    const ratings = [3, 3, 2, 4, 1, 3, 3, 4];
    const elapsed = [0.0, 3, 10, 30, 80, 1, 8, 20];

    // Python reference: [stability, difficulty, interval] per step.
    const expected = [
      [3.173, 5.2824, 3],
      [10.7515, 5.2729, 11],
      [15.149, 6.027, 15],
      [182.6343, 5.3724, 183],
      [6.4358, 6.8574, 0],
      [8.2712, 6.8407, 8],
      [21.3877, 6.8241, 21],
      [120.3518, 6.2946, 120],
    ];

    double? s;
    double? d;
    var reps = 0;
    final now = DateTime(2026, 1, 1);

    for (var i = 0; i < ratings.length; i++) {
      final res = FsrsAlgorithm.calculate(
        stability: s,
        difficulty: d,
        repetitions: reps,
        easeFactor: 2.5,
        interval: 0,
        elapsedDays: (elapsed[i]).toDouble(),
        rating: ratings[i],
        now: now,
      );
      s = res.stability;
      d = res.difficulty;
      reps = res.repetitions;

      expect(res.interval, expected[i][2].toInt(), reason: 'interval @step $i');
      expect(s, closeTo(expected[i][0] as double, 0.01), reason: 'stability @step $i');
      expect(d, closeTo(expected[i][1] as double, 0.01), reason: 'difficulty @step $i');
    }
  });

  test('cardRetrievability matches Python fsrs.card_retrievability', () {
    // (stability, interval, elapsedDays, expectedR) — expectedR from fsrs.py.
    // stability == null seeds from the interval (legacy SM-2 cards).
    const cases = [
      [10.0, 0, 20.0, 0.825029],
      [null, 5, 40.0, 0.589610],
      [50.0, 0, 2.0, 0.995341],
      [null, 1, 100.0, 0.202209],
      [5.0, 0, 40.0, 0.589610],
    ];
    for (final c in cases) {
      final r = FsrsAlgorithm.cardRetrievability(
        stability: c[0] as double?,
        interval: c[1] as int,
        elapsedDays: c[2] as double,
      );
      expect(r, closeTo(c[3] as double, 0.0001),
          reason: 'R for stability=${c[0]} interval=${c[1]} elapsed=${c[2]}');
    }
  });
}
